def _verify(headers, body, secrets, now) -> bool:
    lower = {str(k).lower(): v for k, v in headers.items()}
    event_id = lower.get("corvid-event-id")
    header = lower.get("corvid-signature")
    if not isinstance(event_id, str) or not isinstance(header, str):
        return False
    t = None
    sigs = []
    for element in header.split(","):
        element = element.lstrip(" ")
        key, sep, value = element.partition("=")
        if not sep or not key:
            return False
        if key == "t":
            if t is not None or not _DIGITS.fullmatch(value) or not value.isascii():
                return False
            t = value
        elif key == "v2":
            if _HEX64.fullmatch(value):
                sigs.append(value)
    if t is None or not sigs:
        return False
    ts = int(t)
    if ts < now - 300 or ts > now + 60:
        return False
    payload = b"v2:" + t.encode() + b":" + event_id.encode() + b":" + bytes(body)
